const item = $input.item.json;
const rows = (item.values || []).slice(1); // skip header

// columns: [prospectId, companyName, domain, industry, contactName, contactTitle, contactEmail, status]
const prospects = rows
  .map((r, i) => ({ r, rowIndex: i + 2 })) // +2: header row + 1-indexed sheet rows
  .filter(({ r }) => (r[7] || '').toLowerCase() === 'new')
  .map(({ r, rowIndex }) => ({
    prospectId: r[0] || '',
    companyName: r[1] || '',
    domain: r[2] || '',
    industry: r[3] || '',
    contactName: r[4] || '',
    contactTitle: r[5] || '',
    contactEmail: r[6] || '',
    status: r[7] || '',
    rowIndex
  }));

return { json: { prospects } };

const prospect = $('Split Out - Prospects').item.json;
const item = $input.item.json;

const rawResults = item.news_results || item.organic_results || [];
const newsResults = rawResults.slice(0, 5).map(n => ({
  title: n.title || '',
  snippet: n.snippet || '',
  link: n.link || '',
  date: n.date || ''
}));

return {
  json: {
    ...prospect,
    newsResults
  }
};

const prospect = $('Split Out - Prospects').item.json;
const item = $input.item.json;

return {
  json: {
    ...prospect,
    fundingStage: item.funding_stage || item.fundingStage || 'Unknown',
    totalFundingRaised: item.total_funding || item.totalFunding || 'Unknown',
    lastFundingDate: item.last_funding_date || item.lastFundingDate || '',
    employeeCount: item.employee_count || item.employeeCount || 'Unknown',
    technologies: item.technologies || item.tech_stack || []
  }
};

const prospect = $('Split Out - Prospects').item.json;
const item = $input.item.json;

const rawPeople = item.people || item.results || [];
const decisionMakers = rawPeople.slice(0, 5).map(p => ({
  name: p.name || '',
  title: p.title || '',
  linkedinUrl: p.linkedin_url || p.linkedinUrl || '',
  email: p.email || ''
}));

return {
  json: {
    ...prospect,
    decisionMakers
  }
};

const item = $input.item.json;

const newsResults = item.newsResults || [];
const decisionMakers = item.decisionMakers || [];
const technologies = item.technologies || [];
const hasFunding = !!item.fundingStage && item.fundingStage !== 'Unknown';

let priorityScore = 0;
if (newsResults.length > 0) priorityScore += 25;
if (hasFunding && /series|seed|ipo/i.test(item.fundingStage)) priorityScore += 30;
if (decisionMakers.length > 0) priorityScore += 25;
if (technologies.length > 0) priorityScore += 20;
priorityScore = Math.min(100, priorityScore);

let researchCompletenessScore = 0;
researchCompletenessScore += newsResults.length > 0 ? 25 : 0;
researchCompletenessScore += hasFunding ? 25 : 0;
researchCompletenessScore += decisionMakers.length > 0 ? 25 : 0;
researchCompletenessScore += technologies.length > 0 ? 25 : 0;

return {
  json: {
    ...item,
    priorityScore,
    researchCompletenessScore,
    researchedAt: new Date().toISOString()
  }
};

parameters.text:
=You are an expert B2B sales research analyst preparing a prospect brief for an Account Executive.

Company: {{ $json.companyName }}
Domain: {{ $json.domain }}
Industry: {{ $json.industry }}
Primary Contact: {{ $json.contactName }} ({{ $json.contactTitle }})

Recent News:
{{ JSON.stringify($json.newsResults) }}

Funding & Company Data:
Funding Stage: {{ $json.fundingStage }}
Total Funding Raised: {{ $json.totalFundingRaised }}
Last Funding Date: {{ $json.lastFundingDate }}
Employee Count: {{ $json.employeeCount }}
Technologies Detected: {{ JSON.stringify($json.technologies) }}

Decision Makers:
{{ JSON.stringify($json.decisionMakers) }}

Write a concise, actionable sales research brief. Focus only on facts useful for a first outreach conversation. Do not invent facts that are not present above; where data is missing, say so rather than guessing.

Return a JSON object with EXACTLY these fields:
{
  "companyOverview": "2-3 sentence summary of what the company does and its current stage",
  "recentNewsSummary": "1-2 sentence summary of the most relevant recent news, or 'No recent news found'",
  "fundingSummary": "1 sentence summary of funding status and what it implies for buying power",
  "techStackSummary": "1 sentence summary of relevant technologies and a possible integration or replacement angle",
  "keyDecisionMakers": [ { "name": "", "title": "", "whyRelevant": "" } ],
  "painPointsAndOpportunities": ["short bullet", "short bullet"],
  "personalizedIcebreakers": ["short opener referencing something specific about the company", "second option"],
  "recommendedOutreachChannel": "email, phone, or LinkedIn",
  "recommendedTiming": "short guidance on timing based on news/funding signals",
  "outreachMessageDraft": "A short, personalized first-touch outreach message under 500 characters"
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    companyOverview: `${item.companyName || 'This company'} is in the ${item.industry || 'unknown'} industry. Automated brief generation failed; manual review recommended.`,
    recentNewsSummary: (item.newsResults && item.newsResults.length) ? `${item.newsResults.length} recent news item(s) found; see raw research data.` : 'No recent news found',
    fundingSummary: item.fundingStage ? `Funding stage: ${item.fundingStage}.` : 'Funding data unknown.',
    techStackSummary: (item.technologies && item.technologies.length) ? `Detected technologies: ${item.technologies.join(', ')}.` : 'No technology data found.',
    keyDecisionMakers: item.decisionMakers || [],
    painPointsAndOpportunities: [],
    personalizedIcebreakers: [],
    recommendedOutreachChannel: 'email',
    recommendedTiming: 'No timing signal available; use standard cadence.',
    outreachMessageDraft: `Hi ${item.contactName || 'there'}, wanted to reach out regarding ${item.companyName || 'your company'}.`
  };
}
return {
  json: {
    ...item,
    ...parsed
  }
};

const item = $input.item.json;
const generatedAt = new Date().toISOString();

const decisionMakersStr = (item.keyDecisionMakers || [])
  .map(d => `${d.name || ''} (${d.title || ''})${d.whyRelevant ? ' - ' + d.whyRelevant : ''}`)
  .join(' | ');
const painPointsStr = (item.painPointsAndOpportunities || []).join(' | ');
const icebreakersStr = (item.personalizedIcebreakers || []).join(' | ');

return {
  json: {
    ...item,
    generatedAt,
    salesBriefRow: [
      generatedAt,
      item.prospectId || '',
      item.companyName || '',
      item.contactName || '',
      item.contactTitle || '',
      item.priorityScore || 0,
      item.companyOverview || '',
      item.recentNewsSummary || '',
      item.fundingSummary || '',
      item.techStackSummary || '',
      decisionMakersStr,
      painPointsStr,
      icebreakersStr,
      item.recommendedOutreachChannel || '',
      item.recommendedTiming || '',
      item.outreachMessageDraft || ''
    ]
  }
};

